/*
 * A192648  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and x^2-y^2>0 then x^2-y^2 is in S, and 2 and 3 are in S.
 * https://oeis.org/A192648
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   sequence described in OEIS A192648 by generating the set S:
 *            start with 2 and 3; whenever x>y in S then x^2-y^2 is added to
 *            S. The sequence lists S in increasing order
 * Range:     u8 n <= 5, u16 n <= 14, u32 n <= 932, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* ---------- dynamic arrays for the sequence and helper data ---------- */
static seq_t *S = NULL;
static size_t S_len = 0, S_cap = 0;          /* current length and capacity */

static size_t *next_i_arr = NULL;
static size_t next_cap = 0;                 /* capacity for next_i_arr */

/* ---------- priority queue for candidates (min‑heap) ---------- */
typedef struct { seq_t val; size_t j; } HeapNode;
static HeapNode *heap = NULL;
static size_t heap_size = 0, heap_cap = 0;

/* ---------- utility to enlarge integer array capacity ---------- */
static void ensure_cap_seq(size_t *cap, seq_t **arr, size_t needed) {
    if (needed > *cap) {
        size_t new_cap = (*cap == 0) ? 4 : *cap * 2;
        while (new_cap < needed) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(*arr, new_cap * sizeof(seq_t));
        *arr = tmp;
        *cap = new_cap;
    }
}
static void ensure_cap_size(size_t *cap, size_t **arr, size_t needed) {
    if (needed > *cap) {
        size_t new_cap = (*cap == 0) ? 4 : *cap * 2;
        while (new_cap < needed) new_cap <<= 1;
        size_t *tmp = (size_t *)realloc(*arr, new_cap * sizeof(size_t));
        *arr = tmp;
        *cap = new_cap;
    }
}
static void ensure_cap_heap(size_t *cap, HeapNode **arr, size_t needed) {
    if (needed > *cap) {
        size_t new_cap = (*cap == 0) ? 4 : *cap * 2;
        while (new_cap < needed) new_cap <<= 1;
        HeapNode *tmp = (HeapNode *)realloc(*arr, new_cap * sizeof(HeapNode));
        *arr = tmp;
        *cap = new_cap;
    }
}

/* ---------- heap operations ---------- */
static inline void heap_push(size_t j, seq_t val) {
    ensure_cap_heap(&heap_cap, &heap, heap_size + 1);
    size_t idx = heap_size;
    heap[heap_size++] = (HeapNode){val, j};
    /* bubble up */
    while (idx > 0) {
        size_t parent = (idx - 1) >> 1;
        if (heap[parent].val <= heap[idx].val) break;
        HeapNode tmp = heap[parent];
        heap[parent] = heap[idx];
        heap[idx] = tmp;
        idx = parent;
    }
}
static inline HeapNode heap_pop(void) {
    HeapNode root = heap[0];
    heap[0] = heap[--heap_size];
    size_t idx = 0;
    while (1) {
        size_t left = (idx << 1) + 1;
        size_t right = left + 1;
        size_t smallest = idx;
        if (left < heap_size && heap[left].val < heap[smallest].val)
            smallest = left;
        if (right < heap_size && heap[right].val < heap[smallest].val)
            smallest = right;
        if (smallest == idx) break;
        HeapNode tmp = heap[smallest];
        heap[smallest] = heap[idx];
        heap[idx] = tmp;
        idx = smallest;
    }
    return root;
}

/* ---------- compute candidate value (x^2 - y^2) safely ---------- */
#if defined(__SIZEOF_INT128__) || defined(__int128)
    #define HAVE_INT128 1
#else
    #define HAVE_INT128 0
#endif

static inline seq_t compute_val(size_t i, size_t j) {
    seq_t a = S[i];
    seq_t b = S[j];
    seq_t diff = a - b;
    seq_t sum  = a + b;
#if HAVE_INT128
    return (seq_t)((unsigned __int128)diff * sum);
#else
    return diff * sum;
#endif
}

/* ---------- main OEIS sequence function ---------- */
seq_t a(idx_t n) {
    if (n == 0) return 0;   /* undefined for n<1, but return 0 */

    /* ----- initialise the sequence (once) ----- */
    if (S_len == 0) {
        /* start with 2,3 */
        ensure_cap_seq(&S_cap, &S, 4);
        S[0] = 2;
        S[1] = 3;
        S_len = 2;

        /* next_i array */
        ensure_cap_size(&next_cap, &next_i_arr, 4);
        next_i_arr[0] = 1;            /* next index after 0 */
        next_i_arr[1] = 2;            /* next index after 1 */

        /* heap initial candidate (j=0, i=1) */
        heap_push(0, compute_val(1, 0));
    }

    /* ----- extend sequence until we have n terms ----- */
    while (S_len < (size_t)n) {
        /* pop smallest candidate */
        HeapNode cand = heap_pop();
        size_t j = cand.j;
        seq_t val = cand.val;

        /* advance next index for this j */
        next_i_arr[j]++;

        /* check if this candidate produces a new distinct value */
        bool added = false;
        if (val != S[S_len - 1]) {          /* no duplicate, as S is sorted */
            ensure_cap_seq(&S_cap, &S, S_len + 2);
            S[S_len] = val;
            added = true;
            ++S_len;

            /* prepare next_i for the new element */
            size_t newIndex = S_len - 1;
            ensure_cap_size(&next_cap, &next_i_arr, S_len + 1);
            next_i_arr[newIndex] = newIndex + 1;   /* will point past end */

            /* For all existing j where next_i[j] == newIndex, push candidate */
            for (size_t jj = 0; jj < newIndex; ++jj) {
                if (next_i_arr[jj] == newIndex) {
                    heap_push(jj, compute_val(newIndex, jj));
                }
            }
        }

        /* push next candidate for current j if possible */
        if (next_i_arr[j] < S_len) {
            heap_push(j, compute_val(next_i_arr[j], j));
        }
    }

    return S[n - 1];
}
